/* 案件数据（编码存储）—— 直接看源码只能看到编码串，不直接暴露凶手与真相。
   解码在运行时完成，不联网。 */
(function () {
  var s = '';
  var bin = atob(s), bytes = new Uint8Array(bin.length);
  for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i) ^ 0x5A;
  var txt = new TextDecoder('utf-8').decode(bytes);
  window.CASES = JSON.parse(txt);
})();
